edits.oldText:
export function shouldRetry(status: number) {
  return status === 429 || status >= 500;
}

edits.newText:
export function shouldRetry(status: number, method: string) {
  // Retry on 429 only for safe methods GET and HEAD
  if (status === 429) {
    return method === "GET" || method === "HEAD";
  }
  // Retry on all 5xx statuses for any method
  return status >= 500;
}

